def toks(s): return set(w for w in re.findall(r\"[a-z][a-z0-9'-]+\",(s or '').lower()) if w not in stop and len(w)>2)
arts=[]; inv=collections.defaultdict(list)
for j,line in enumerate(open('articles/2026/03/26/articles.jsonl')):
